function lowestCommonAncestor(root, p, q) {
  // Record every node's parent with a breadth-first walk.
  const parent = new Map([[root, null]]);
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    for (const child of [queue[i].left, queue[i].right]) {
      if (child) { parent.set(child, queue[i]); queue.push(child); }
    }
  }
  // Write out both root-to-node paths and keep the last node they share.
  const pathFromRoot = node => { const path = []; for (; node; node = parent.get(node)) path.push(node); return path.reverse(); };
  const toP = pathFromRoot(p), toQ = pathFromRoot(q);
  let k = 0;
  while (k + 1 < toP.length && k + 1 < toQ.length && toP[k + 1] === toQ[k + 1]) k++;
  return toP[k];
}

